import { createServer } from 'vite'
import { fileURLToPath } from 'node:url'
import { copyFile, mkdir, mkdtemp, realpath, rm, writeFile } from 'node:fs/promises'
import { basename, dirname, join, relative } from 'node:path'
import { setTimeout } from 'node:timers/promises'
import assert from 'node:assert/strict'

const repository = fileURLToPath(new URL('..', import.meta.url))
const originalApp = join(repository, 'clients/desktop/app')
await mkdir(join(originalApp, '.local'), { recursive: true })
const parent = await realpath(join(originalApp, '.local'))
const root = await mkdtemp(join(parent, 'renderer-readiness-'))
const app = join(root, 'clients/desktop/app')
const events: object[] = []
const started = performance.now()
const record = (event: string, details: object = {}) => {
  events.push({ elapsedMs: Math.round((performance.now() - started) * 100) / 100, event, ...details })
}
const runtime = join(app, 'config/vite/vite.config.main.ts')
const external = join(root, 'package/config/typescript/tsconfig.lib.json')
let generation = 0
let server: Awaited<ReturnType<typeof createServer>> | undefined

try {
  await mkdir(dirname(runtime), { recursive: true })
  await mkdir(dirname(external), { recursive: true })
  await copyFile(join(originalApp, 'config/vite/vite.config.renderer.ts'), join(app, 'config/vite/vite.config.renderer.ts'))
  for (const name of ['main', 'reader', 'player', 'game-panel']) {
    const directory = join(app, 'src/renderer/windows', name)
    await mkdir(directory, { recursive: true })
    await writeFile(join(directory, 'index.html'), '<!doctype html><main>Watcher readiness probe</main>')
  }
  await writeFile(join(app, 'package.json'), '{"type":"module"}')
  await writeFile(runtime, 'export default {}\n')
  await writeFile(external, '{}\n')

  server = await createServer({
    configFile: join(app, 'config/vite/vite.config.renderer.ts'),
    mode: 'development',
    plugins: [{
      name: 'observe-watcher-readiness',
      configureServer(vite) {
        const current = generation++
        record('configure-server', { generation: current })
        vite.watcher.on('ready', () => record('watcher-ready', { generation: current }))
        vite.watcher.on('all', (event, path) => record('watcher-event', { generation: current, kind: event, path: relative(root, path) }))
        vite.watcher.add([runtime, dirname(external)])
      },
    }],
  })
  await server.listen()
  record('listen-returned')

  for (let restart = 0; restart < 3; restart++) {
    await server.restart()
    record('restart-returned', { restart })
    for (const [kind, path] of [['runtime', runtime], ['package', external]] as const) {
      const watched = server.watcher.getWatched()
      record('write-start', { restart, kind, presentInGetWatched: watched[dirname(path)]?.includes(basename(path)) ?? false })
      await writeFile(path, kind === 'runtime' ? `export default { attempt: ${restart} }\n` : `{"attempt":${restart}}\n`)
      record('write-finished', { restart, kind })
      await setTimeout(1_100)
    }
  }
} finally {
  await server?.close()
  record('server-closed')
  const resolved = await realpath(root)
  assert.equal(dirname(resolved), parent)
  assert.ok(basename(resolved).startsWith('renderer-readiness-'))
  await rm(resolved, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 })
  await mkdir(join(originalApp, 'test-results/watch-diagnostics'), { recursive: true })
  const report = { platform: process.platform, arch: process.arch, node: process.version, note: 'Public Vite watcher observation in an isolated fixture on the recorded host.', events }
  await writeFile(join(originalApp, 'test-results/watch-diagnostics/readiness.json'), JSON.stringify(report, null, 2) + '\n')
  console.log(JSON.stringify(report, null, 2))
}

import { afterAll, beforeAll, expect, test, vi } from 'vitest'
import { copyFile, mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import { startRenderer } from '../../tools/dev/renderer'

const paths = vi.hoisted(() => ({ appRoot: '', repositoryRoot: '' }))
// Only relocate owned files; use the actual Vite configuration, server and watcher.
vi.mock('../../tools/lib/paths', () => paths)

let renderer: Awaited<ReturnType<typeof startRenderer>> | undefined
const changes: string[] = []

beforeAll(async () => {
  const originalApp = fileURLToPath(new URL('../..', import.meta.url))
  await mkdir(join(originalApp, '.local'), { recursive: true })
  paths.repositoryRoot = await mkdtemp(join(originalApp, '.local', 'renderer-test-'))
  paths.appRoot = join(paths.repositoryRoot, 'clients/desktop/app')
  for (const directory of [
    'config/vite',
    'src/main',
    'src/preload',
    'src/extension-host',
    'src/shared',
    'native',
    'assets',
  ]) {
    await mkdir(join(paths.appRoot, directory), { recursive: true })
  }
  await copyFile(
    join(originalApp, 'config/vite/vite.config.renderer.ts'),
    join(paths.appRoot, 'config/vite/vite.config.renderer.ts'),
  )
  for (const name of ['main', 'reader', 'player', 'game-panel']) {
    const directory = join(paths.appRoot, 'src/renderer/windows', name)
    await mkdir(directory, { recursive: true })
    await writeFile(join(directory, 'index.html'), '<!doctype html><main>Watcher fixture</main>')
  }
  await writeFile(join(paths.appRoot, 'package.json'), '{"type":"module"}')
  await writeFile(join(paths.appRoot, 'config/vite/vite.config.main.ts'), 'export default {}\n')
  await writeFile(join(paths.repositoryRoot, 'pnpm-lock.yaml'), 'lockfileVersion: 9\n')
  const member = join(paths.repositoryRoot, 'package')
  await mkdir(join(member, 'config/typescript'), { recursive: true })
  await writeFile(join(member, 'package.json'), '{"name":"@kisaki3/watch-fixture"}')
  await writeFile(join(member, 'config/typescript/tsconfig.lib.json'), '{}\n')
  renderer = await startRenderer(
    [{ name: '@kisaki3/watch-fixture', path: member }],
    join(paths.repositoryRoot, 'snapshots'),
  )
  renderer.watch((change) => changes.push(change))
  // Initial adoption restarts Vite. Watch subscriptions must survive that real restart.
  await renderer.adopt({ id: 'empty-fixture', sizeBytes: 0, packages: new Map() })
})

afterAll(async () => {
  await renderer?.close()
  if (paths.repositoryRoot) {
    // Vite may still finish a cache write as its server closes; retry transient directory removal.
    await rm(paths.repositoryRoot, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 })
  }
})

test('runtime configuration and nested public-package inputs remain watched after Vite restarts', async () => {
  for (const [path, content, kind] of [
    [
      join(paths.appRoot, 'config/vite/vite.config.main.ts'),
      'export default { mode: "development" }\n',
      'runtime',
    ],
    [
      join(paths.appRoot, 'package.json'),
      '{"type":"module","imports":{"#fixture":"./src/main/entry.ts"}}',
      'runtime',
    ],
    [
      join(paths.repositoryRoot, 'package/config/typescript/tsconfig.lib.json'),
      '{"compilerOptions":{"strict":true}}',
      'public-package',
    ],
    [join(paths.appRoot, 'src/main/added.ts'), 'export const value = 1\n', 'runtime'],
  ] as const) {
    const before = changes.filter((change) => change === kind).length
    await writeFile(path, content)
    await expect
      .poll(() => changes.filter((change) => change === kind).length, {
        message: `Expected ${kind} notification for ${relative(paths.repositoryRoot, path)}`,
      })
      .toBeGreaterThan(before)
  }
})
